description:
Integrate GNSS time with channel selection in link_ctx.c.

## File
lichen/subsys/lichen/link/link_ctx.c

## Changes to lichen_link_channel_select

### Add GNSS-synced path
```c
#ifdef CONFIG_LICHEN_SYNC_HOP
#include <lichen/sync_hop.h>
#include <lichen/hal/time.h>

int lichen_link_channel_select_sync(const uint8_t eui64[LICHEN_EUI64_LEN],
                                     uint8_t num_channels,
                                     uint8_t *channel)
{
    struct lichen_hal_time_snapshot ts;

    /* Try GNSS time first */
    if (lichen_hal_time_snapshot_get(&ts) == 0 && ts.gnss_valid) {
        uint32_t sfn = lichen_sfn_from_unix_ms(ts.unix_time_ms);
        *channel = lichen_sync_hop_channel(sfn, 
                                           CONFIG_LICHEN_SYNC_HOP_SEED,
                                           num_channels);
        return 0;
    }

#ifdef CONFIG_LICHEN_SYNC_HOP_FALLBACK
    /* Fallback to epoch-based */
    return lichen_link_channel_select(eui64, num_channels, channel);
#else
    return -ENODATA;
#endif
}
#endif /* CONFIG_LICHEN_SYNC_HOP */
```

### Header Declaration
Add to link.h:
```c
#ifdef CONFIG_LICHEN_SYNC_HOP
int lichen_link_channel_select_sync(const uint8_t eui64[LICHEN_EUI64_LEN],
                                     uint8_t num_channels,
                                     uint8_t *channel);
#endif
```

## Dependencies
- Issue: Zephyr Kconfig options
- Issue: Zephyr sync_hop.c/h
- Requires lichen_hal_time_snapshot_get() with GNSS support
